/* eslint-disable @typescript-eslint/ban-types */
import type { Hooks, TableInstance } from 'react-table';

/** Options on the useTable config object added by the useZebraRowStyles plugin hook. */
export interface UseZebraRowStylesOptions {
  /** Disables the alternating row styles a.k.a. as zebra. */
  disableZebraRowStyles?: boolean;
}

/** Defines props added to the table body when useZebraRowStyles plugin hook is used. */
export interface UseZebraRowStylesTableBodyProps {
  /**
   * Data attribute that will be applied to the table when
   * the alternating row styles are enabled.
   */
  enableZebra?: boolean;
}

/** Uses the table instance to manipulate and extend the table behavior */
function useInstance(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  instance: TableInstance<any>,
) {
  const { disableZebraRowStyles, getHooks } = instance;
  if (!disableZebraRowStyles) {
    getHooks().getTableBodyProps.push((props) => {
      const additionalTableProps: UseZebraRowStylesTableBodyProps = {
        enableZebra: true,
      };
      return [props, additionalTableProps];
    });
  }
}

/**
 * Table hook that enables alternating row styles a.k.a. zebra styles.
 */
export function useZebraRowStyles<
  D extends Record<string, unknown> = Record<string, unknown>,
>(hooks: Hooks<D>): void {
  hooks.useInstance.push(useInstance);
}

useZebraRowStyles.pluginName = 'useZebraRowStyles';
